pm.test("200: до двух клиентов, отсортированных по id", () => {
  pm.response.to.have.status(200);

  const users = pm.response.json();
  pm.expect(users).to.be.an("array");
  pm.expect(users.length).to.be.within(1, 2);

  users.forEach((user, index) => {
    pm.expect(user).to.have.all.keys("id", "login", "first_name", "last_name", "role");
    pm.expect(Number.isInteger(user.id) && user.id > 0).to.be.true;
    pm.expect(user.role).to.equal("client");

    if (index > 0) {
      pm.expect(user.id).to.be.greaterThan(users[index - 1].id);
    }
  });

  pm.collectionVariables.set("user_id", String(users[0].id));
});

pm.test("200: получен запрошенный пользователь", () => {
  pm.response.to.have.status(200);

  const user = pm.response.json();
  pm.expect(user).to.have.all.keys(
    "id", "login", "first_name", "last_name", "role"
  );
  pm.expect(user.id).to.equal(Number(pm.variables.get("user_id")));
  pm.expect(user.role).to.be.oneOf(["client", "master", "admin"]);
});

pm.test("200: роль запрошенного пользователя установлена", () => {
  pm.response.to.have.status(200);

  const user = pm.response.json();
  pm.expect(user).to.have.all.keys(
    "id", "login", "first_name", "last_name", "role"
  );
  pm.expect(user.id).to.equal(Number(pm.variables.get("user_id")));
  pm.expect(user.role).to.equal("master");
});

